function sortBy<T, K extends keyof T>(items: T[], key: K, direction: "asc" | "desc" = "asc"): T[] {
    return [...items].sort((a, b) => {
        const av = a[key]
        const bv = b[key]
        const result = av < bv ? -1 : av > bv ? 1 : 0
        return direction === "asc" ? result : -result
    })
}

