function uniqueBy<T>(items: T[], key: (x: T) => unknown): T[] {
    const seen = new Set<unknown>()
    return items.filter(x => {
        const k = key(x)
        if (seen.has(k)) return false
        seen.add(k)
        return true
    })
}

