class Queue<T> {
    private items: T[] = []

    enqueue(item: T): this {
        this.items.push(item)
        return this
    }

    dequeue(): T | undefined {
        return this.items.shift()
    }

    peek(): T | undefined {
        return this.items[0]
    }

    get size(): number {
        return this.items.length
    }

    get isEmpty(): boolean {
        return this.items.length === 0
    }
}

const tasks = new Queue<{ id: number; title: string }>()
tasks.enqueue({ id: 1, title: "Birinchi" }).enqueue({ id: 2, title: "Ikkinchi" })

console.log("Navbatdagi:", tasks.peek()?.title)
console.log("Bajarilmoqda:", tasks.dequeue()?.title)
console.log("Qoldi:", tasks.size, "| bo'shmi:", tasks.isEmpty)

interface Entity {
    id: number
}

class InMemoryRepository<T extends Entity> {
    private items = new Map<number, T>()

    save(item: T): T {
        this.items.set(item.id, item)
        return item
    }

    findById(id: number): T | undefined {
        return this.items.get(id)
    }

    findAll(): T[] {
        return [...this.items.values()]
    }

    delete(id: number): boolean {
        return this.items.delete(id)
    }

    count(): number {
        return this.items.size
    }
}

type Product = Entity & { name: string; price: number }

const repo = new InMemoryRepository<Product>()
repo.save({ id: 1, name: "Kitob", price: 45_000 })
repo.save({ id: 2, name: "Ruchka", price: 5_000 })

console.log(repo.findById(1)?.name)
console.log("Jami:", repo.count())
repo.delete(1)
console.log("O'chirilgandan keyin:", repo.findAll().map(p => p.name))

