    private head: ListNode<T> | null = null
    private length = 0

    add(value: T): this {
        const node: ListNode<T> = { value, next: null }
        if (!this.head) {
            this.head = node
        } else {
            let current = this.head
            while (current.next) current = current.next
            current.next = node
        }
        this.length++
        return this
    }

    toArray(): T[] {
        const result: T[] = []
        let current = this.head
        while (current) {
            result.push(current.value)
            current = current.next
        }
        return result
    }

    get size(): number {
        return this.length
    }
}

