class LinkedList<T> {
    private head: Item<T> | null = null
    private tail: Item<T> | null = null

    append(value: T): this {
        const item: Item<T> = { value, next: null }
        if (this.tail) this.tail.next = item
        else this.head = item
        this.tail = item
        return this
    }

    *[Symbol.iterator](): Generator<T> {
        let current = this.head
        while (current) {
            yield current.value
            current = current.next
        }
    }
}

