function once<F extends (...args: any[]) => any>(fn: F): (...args: Parameters<F>) => ReturnType<F> {
    let done = false
    let result: ReturnType<F>
    return (...args) => {
        if (!done) { done = true; result = fn(...args) }
        return result
    }
}

